import { clerkMiddleware, createRouteMatcher } from "@clerk/nextjs/server";
import { neon } from "@neondatabase/serverless";
import { and, eq } from "drizzle-orm";
import { drizzle } from "drizzle-orm/neon-http";
import { NextResponse } from "next/server";
import { publications } from "@/db/schema";

// Define public routes
const isPublicRoute = createRouteMatcher([
  "/",
  "/sign-in(.*)",
  "/sign-up(.*)",
  "/api/webhooks/clerk",
  "/unsubscribe(.*)",
  "/@(.*)",
]);

export default clerkMiddleware(async (auth, request) => {
  const url = request.nextUrl;
  const hostname = request.headers.get("host") || "";

  // The main domain where the platform is hosted
  const mainDomain =
    process.env.NEXT_PUBLIC_APP_URL?.replace("https://", "").replace(
      "http://",
      "",
    ) || "kraken.krishg.com";

  // 1. Handle Custom Domain Rewriting
  if (
    hostname !== mainDomain &&
    !hostname.includes("localhost") &&
    !hostname.endsWith(".vercel.app")
  ) {
    const slug = await getSlugForCustomDomain(hostname);
    if (slug) {
      // Rewrite custom domain to /@slug/...
      return NextResponse.rewrite(
        new URL(`/@${slug}${url.pathname}`, request.url),
      );
    }
  }

  // 2. Auth Protection
  if (!isPublicRoute(request)) {
    await auth.protect();
  }

  return NextResponse.next();
});

// This would typically involve a database query or an Edge Config lookup
async function getSlugForCustomDomain(
  hostname: string,
): Promise<string | null> {
  if (!process.env.DATABASE_URL) return null;

  const sql = neon(process.env.DATABASE_URL);
  const db = drizzle(sql);

  const [publication] = await db
    .select({ slug: publications.slug })
    .from(publications)
    .where(
      and(
        eq(publications.customDomain, hostname),
        eq(publications.customDomainVerified, true),
      ),
    )
    .limit(1);

  return publication?.slug || null;
}

export const config = {
  matcher: [
    // Skip Next.js internals and static files, unless found in search params
    "/((?!_next|[^?]*\\.(?:html?|css|js(?!on)|jpe?g|webp|png|gif|svg|ttf|woff2?|ico|csv|docx?|xlsx?|zip|webmanifest)).*)",
    // Always run for API routes
    "/(api|trpc)(.*)",
  ],
};

"use server";

import { eq } from "drizzle-orm";
import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { db } from "@/db";
import { publications, users } from "@/db/schema";

export async function createPublication(formData: FormData) {
  const userId = formData.get("userId") as string;
  const username = formData.get("username") as string;
  const name = formData.get("name") as string;
  const description = formData.get("description") as string;

  if (!userId || !username || !name) {
    return { error: "Missing required fields" };
  }

  // Check username uniqueness (in users table)
  const existingUser = await db.query.users.findFirst({
    where: eq(users.username, username),
  });

  if (existingUser && existingUser.id !== userId) {
    return { error: "Username already taken" };
  }

  // Update user username if changed
  await db.update(users).set({ username }).where(eq(users.id, userId));

  // Create publication
  try {
    await db.insert(publications).values({
      userId,
      name,
      description,
      slug: username, // Initially publication slug matches username
    });
  } catch (err) {
    console.error("Failed to create publication:", err);
    return { error: "Could not create publication. Try a different username." };
  }

  revalidatePath("/");
  redirect("/");
}

"use server";

import { eq } from "drizzle-orm";
import { revalidatePath } from "next/cache";
import { db } from "@/db";
import { issues } from "@/db/schema";

export async function saveIssue(
  issueId: string,
  data: Partial<typeof issues.$inferInsert>,
) {
  await db
    .update(issues)
    .set({
      ...data,
      updatedAt: new Date(),
    })
    .where(eq(issues.id, issueId));

  revalidatePath(`/editor/${issueId}`);
}

export async function createIssue(publicationId: string) {
  // Get highest edition number
  const latestIssue = await db.query.issues.findFirst({
    where: eq(issues.publicationId, publicationId),
    orderBy: (issues, { desc }) => [desc(issues.editionNumber)],
  });

  const editionNumber = (latestIssue?.editionNumber || 0) + 1;

  const newIssue = await db
    .insert(issues)
    .values({
      publicationId,
      title: "Untitled Issue",
      editionNumber,
      content: "",
      status: "draft",
    })
    .returning();

  return newIssue[0];
}

import { redirect } from "next/navigation";
import { sendIssueBroadcast } from "@/lib/loops";

export async function publishIssue(issueId: string) {
  const issue = await db.query.issues.findFirst({
    where: eq(issues.id, issueId),
    with: {
      publication: true,
    },
  });

  if (!issue) return;

  await db
    .update(issues)
    .set({
      status: "published",
      publishedAt: new Date(),
      updatedAt: new Date(),
    })
    .where(eq(issues.id, issueId));

  // Send emails via Loops broadcast
  await sendIssueBroadcast(
    issue.publication.name,
    issue.title,
    issue.editionNumber,
    issue.content,
    `subscribed-${issue.publication.slug}`,
  );

  revalidatePath("/");
  revalidatePath(`/editor/${issueId}`);
  revalidatePath(`/@${issue.publication.slug}`);
  revalidatePath(`/@${issue.publication.slug}/issue/${issue.editionNumber}`);
  redirect(`/@${issue.publication.slug}/issue/${issue.editionNumber}`);
}
